    backupReminderToast: 'काफ़ी समय हो गया है - अपने सेव का बैकअप लेने पर विचार करें (अकाउंट और डेटा)',
    saveSizeLabel: 'लोकल सेव साइज़',
    clearCacheLabel: 'कैश / अस्थायी डेटा साफ़ करें',
