    htpRules: 'ईमानदारी से खेलो - कोई चीटिंग, बग का फ़ायदा उठाना, या लीडरबोर्ड स्कोर से छेड़छाड़ नहीं। अपना निकनेम साफ़-सुथरा और सम्मानजनक रखो। कोई बग मिला या कोई नियम तोड़ रहा है? Discord पर रिपोर्ट करो।',
