    loadoutBalancedBlurb: 'Sin un pasado en particular. Cogiste un arma porque todos lo hacían.',
    loadoutRunnerBlurb: 'Rápido de pies, siempre lo has sido. Nunca aprendiste a encajar un golpe.',
    loadoutTankBlurb: 'Has aguantado cosas peores que esto antes. Solo que no esperes esquivarlo corriendo.',
